steps.script:
var p = PhaseManager.get_current_phase_instance()
for i in range(4):
	if p == null or not p.has_pending_stratagem_window():
		break
	var w = p.get_pending_stratagem_window()
	if str(w.get("window_id", "")) != "movement_phase_start":
		break
	NetworkIntegration.route_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(w.get("player", 1)), "window_id": str(w.get("window_id", ""))})
return p != null and not p.has_pending_stratagem_window()

for c in tree.root.get_children():
	if c is Window and c != tree.root and str(c.name) == "DisembarkDialog":
		c.hide()
		c.queue_free()
return true

var ph = PhaseManager.get_current_phase_instance()
if ph.get("_awaiting_reroll_decision"):
	NetworkIntegration.route_action({"type": "DECLINE_COMMAND_REROLL", "actor_unit_id": "U_CORONUS_A", "player": 2})
for c in tree.root.get_children():
	if c is Window and c != tree.root and str(c.name).begins_with("CommandReroll"):
		c.hide()
		c.queue_free()
return bool(GameState.get_unit("U_CORONUS_A").flags.get("advanced", false))

var ul = tree.current_scene.movement_controller.unit_list
var out := []
for i in range(ul.get_item_count()):
	out.append("%d=%s:%s" % [i, str(ul.get_item_metadata(i)), ul.get_item_text(i)])
print("[wp-g2] movement unit list: ", out)
for i in range(ul.get_item_count()):
	if str(ul.get_item_metadata(i)) == "U_GUARD_A":
		return ul.get_item_text(i).contains("Click to Disembark")
return false
